"""

import logging
import pytest
from browser_use.llm.litellm.serializer import LiteLLMMessageSerializer


class DummyPart:
    def __init__(self, type_: str):
        self.type = type_
        # attributes accessed only for known types; provide dummies
        self.text = "dummy"
        self.image_url = None


def test_unsupported_content_part_logs_warning(caplog):
    part = DummyPart('unknown')
    with caplog.at_level(logging.WARNING):
        result = LiteLLMMessageSerializer._serialize_user_content([part])
    # No parts should be added
    assert result == []
    # A warning about the unsupported type should be logged
    assert any('Unsupported content part type: unknown' in record.message for record in caplog.records)
